// Embedded so link-preview images render with the brand font on any runtime (node or edge).
const FIGTREE_500 = "";
const FIGTREE_800 = "";

function toBuffer(b64: string): ArrayBuffer {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out.buffer;
}

let cache: { name: string; data: ArrayBuffer; weight: 500 | 800; style: "normal" }[] | null = null;

/** Fonts option for next/og ImageResponse. */
export function ogFonts() {
  if (!cache) {
    cache = [
      { name: "Figtree", data: toBuffer(FIGTREE_500), weight: 500, style: "normal" },
      { name: "Figtree", data: toBuffer(FIGTREE_800), weight: 800, style: "normal" },
    ];
  }
  return cache;
}
